import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
count = 0
for i in range(n):
    for j in range(i + 1, n):
        if (a[i] ^ a[j]) > (a[i] & a[j]):
            count += 1
print(count)

